 "content": "from collections import deque

def transform(grid):
    """Recolor the prominent irregular color-6 component as color 1."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 9 or (r, c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.setdefault(color,[]).append(cells)
    # The central irregular component is the largest connected color-6 object.
    cells = max(comps.get(6, [[]]), key=len)
    for r,c in cells:
        out[r][c] = 1
    return out
"
